import { APPLIER_SPECS } from "../../lib/game-config-appliers";
import type { GameConfigApplier } from "./types";
import { terrariaApplier } from "./terraria";

/**
 * THE applier registry. To add a family: write worker/game-config-appliers/<family>.ts
 * (+ lib/game-applier-specs/<family>.ts), then add ONE line to `register` below and
 * ONE line to APPLIER_SPECS in lib/game-config-appliers.ts. If the two disagree the
 * worker refuses to boot (and test/game-config-appliers.test.ts fails) — see `assertConsistent`.
 * worker/game-config.ts `applyRealConfig` dispatches here for every family it has no
 * inline applier for.
 */
const REGISTRY = new Map<string, GameConfigApplier>();
function register(a: GameConfigApplier) {
  REGISTRY.set(a.spec.family, a);
}

register(terrariaApplier);

/** The registered spec must be the exact object the UI derives from. */
export function assertConsistent(): void {
  for (const [family, a] of REGISTRY) {
    if (APPLIER_SPECS[family] !== a.spec) throw new Error(`game config applier "${family}": its spec is not the one listed in lib/game-config-appliers.ts APPLIER_SPECS`);
  }
  for (const family of Object.keys(APPLIER_SPECS)) {
    if (!REGISTRY.has(family)) throw new Error(`game config applier "${family}" is in APPLIER_SPECS but not registered in worker/game-config-appliers/index.ts`);
  }
}
assertConsistent();

export function getApplier(family: string): GameConfigApplier | null {
  return REGISTRY.get(family) ?? null;
}
export function registeredFamilies(): string[] {
  return [...REGISTRY.keys()];
}
import type { ApplierContext, ApplyOutcome, GameConfigApplier } from "./types";

/**
 * The runner every applier goes through. It owns the boring, easy-to-get-wrong
 * parts so an applier only contains its own mechanism:
 *   - which fields are in play (handled ∩ changed) and the "saved but not applied" note for the rest
 *   - idempotent no-op when none of the changed fields belong to the applier
 *   - secret redaction of every note (values of spec fields flagged `secret`, plus any
 *     extra strings an applier registers)
 *   - never throws: an exception becomes an honest failed outcome
 */
export type RunBase = Omit<ApplierContext, "touched" | "family"> & { family?: string };

export function redactor(secrets: string[]): (s: string) => string {
  const list = secrets.filter((s) => s.length >= 3);
  return (s) => list.reduce((acc, x) => acc.split(x).join("***"), s);
}

export function secretValues(applier: GameConfigApplier, values: Record<string, unknown>): string[] {
  return Object.entries(applier.spec.fields)
    .filter(([, f]) => f.secret)
    .map(([k]) => String(values[k] ?? ""))
    .filter((v) => v.length > 0);
}

export async function runApplier(applier: GameConfigApplier, base: RunBase): Promise<ApplyOutcome> {
  const { spec } = applier;
  const handled = Object.keys(spec.fields);
  const changed = base.changed?.filter((k) => !k.startsWith("_") && k !== "variant");
  const touched = changed ? handled.filter((k) => changed.includes(k)) : handled;
  const redact = redactor(secretValues(applier, base.values));

  const unhandled = changed ? changed.filter((k) => !(k in spec.fields)) : [];
  const tail = unhandled.length
    ? [`Saved but not applied to the running game: ${unhandled.join(", ")}. We can't push ${unhandled.length === 1 ? "that setting" : "those settings"} to the server yet.`]
    : [];

  if (touched.length === 0) {
    return { ok: true, applied: [], notes: ["Nothing in this change needs to be applied to the running server.", ...tail] };
  }
  try {
    const out = await applier.apply({ ...base, family: base.family ?? spec.family, touched });
    return { ...out, applied: out.applied.map(redact), notes: [...out.notes.map(redact), ...tail] };
  } catch (e) {
    return { ok: false, applied: [], notes: [redact(`Apply failed: ${(e as Error).message}`.slice(0, 300)), ...tail] };
  }
}
import { TERRARIA_SPEC, TERRARIA_CONFIG_FIELDS, TERRARIA_WORLD_FIELDS, TERRARIA_CONFIG_JSON, TERRARIA_CONTAINER, TERRARIA_MAX_SLOTS, TERRARIA_WORLD_DIR, terrariaCmdForWorld, terrariaTshockSettings, terrariaWorldFile, terrariaWorldSpec } from "../../lib/game-applier-specs/terraria";
import type { ApplierContext, ApplyOutcome, GameConfigApplier } from "./types";
import { shq } from "./types";
import { patchRemoteFile } from "./kit/config-file";
import { patchJson, readJson } from "./kit/json-patch";
import { recreateWithEnv } from "./kit/env-recreate";
import { verifyReadback } from "./kit/readback";

/**
 * Terraria (ryshe/terraria = TShock) applier — mixed strategy. Mechanisms and
 * the reasons for them are documented in lib/game-applier-specs/terraria.ts.
 *
 *  1. TShock keys   -> config-file strategy on /opt/terraria/config.json ("Settings" wrapper),
 *                      verified by reading each key back. Takes effect on restart.
 *  2. World fields  -> env-recreate strategy: a new size/name/seed/difficulty gets its own world
 *                      file (WORLD_FILENAME + launch args); the old world file is never touched.
 *                      Only runs when the customer changed one of these fields in this save.
 *  If step 2 fails, step 1 is rolled back too, so a failure always means "nothing changed".
 */

const ENV_FILE = "/root/terraria.env";

function validateConfigJson(content: string): string | null {
  let doc: unknown;
  try {
    doc = JSON.parse(content);
  } catch {
    return "The result is not valid JSON.";
  }
  if (!doc || typeof doc !== "object" || Array.isArray(doc)) return "The result is not a JSON object.";
  return null;
}

async function apply(ctx: ApplierContext): Promise<ApplyOutcome> {
  const { guest, values } = ctx;
  const cfgFields = ctx.touched.filter((k) => (TERRARIA_CONFIG_FIELDS as readonly string[]).includes(k));
  const worldTouched = ctx.changed !== undefined && ctx.touched.some((k) => (TERRARIA_WORLD_FIELDS as readonly string[]).includes(k));
  const applied: string[] = [];
  const notes: string[] = [];
  let restore: (() => Promise<void>) | null = null;
  let commit: (() => Promise<void>) | null = null;

  // ---- 1. TShock config.json ------------------------------------------------
  if (cfgFields.length) {
    const want = terrariaTshockSettings(values, cfgFields);
    const res = await patchRemoteFile(guest, {
      path: TERRARIA_CONFIG_JSON,
      patch: (old) => patchJson(old, Object.entries(want).map(([k, v]) => ({ path: [k], value: v })), { wrapper: "Settings" }),
      validate: validateConfigJson,
    });
    if (res.status === "invalid" || res.status === "failed") return { ok: false, applied: [], notes: [res.reason, "Nothing was changed on your server."] };
    if (res.status === "missing") {
      notes.push("TShock hasn't created its config file yet (the server has never fully started), so these settings were saved but not applied: " + cfgFields.join(", ") + ". Start the server once, then save again.");
    } else if (res.status === "unchanged") {
      notes.push(`TShock's config already matched (${cfgFields.join(", ")}) — nothing to change there.`);
    } else {
      restore = res.restore;
      commit = res.commit;
      const back = await guest.readFile(TERRARIA_CONFIG_JSON);
      const actual: Record<string, unknown> = {};
      for (const k of Object.keys(want)) actual[k] = back === null ? undefined : readJson(back, [k], { wrapper: "Settings" });
      const rb = verifyReadback(want, actual);
      if (!rb.ok) {
        await res.restore();
        return { ok: false, applied: [], notes: [`Verification failed for ${rb.mismatched.join(", ")}; TShock's previous config was restored. Nothing was changed on your server.`] };
      }
      applied.push(`Updated TShock's config (${cfgFields.join(", ")}).`);
      if (Number(values["max-players"]) > TERRARIA_MAX_SLOTS && cfgFields.includes("max-players")) {
        notes.push(`TShock allows at most ${TERRARIA_MAX_SLOTS} players, so Max Players was set to ${TERRARIA_MAX_SLOTS}.`);
      }
    }
  }

  // ---- 2. New world (only when the customer changed a world field) ------------
  let restarted = false;
  if (worldTouched) {
    const spec = terrariaWorldSpec(values);
    const file = terrariaWorldFile(spec);
    const existed = (await guest.exec(`test -f ${shq(`${TERRARIA_WORLD_DIR}/${file}`)}`)).code === 0;
    const r = await recreateWithEnv(guest, {
      container: TERRARIA_CONTAINER,
      unit: ctx.unit,
      env: { WORLD_FILENAME: file },
      cmd: (old) => terrariaCmdForWorld(old, spec),
      envFile: ENV_FILE,
      waitPort: ctx.waitPort,
    });
    if (r.status === "failed") {
      if (restore) await restore().catch(() => undefined);
      return { ok: false, applied: [], notes: [r.note, ...(restore ? ["Your TShock settings were put back as well, so nothing was changed."] : [])] };
    }
    if (r.status === "recreated") {
      restarted = r.wasActive;
      applied.push(
        existed
          ? `Switched to your existing world "${file}".`
          : `Created a new world (${file}) and switched to it. Your previous world is still on the server and was not deleted.`,
      );
      notes.push(...r.notes);
      if (r.wasActive) notes.push("Your server restarted briefly to apply this — connected players were disconnected and can rejoin now.");
    } else if (!applied.length) {
      notes.push("This server is already running that world — nothing to change.");
    }
  }

  if (commit) await commit().catch(() => undefined);
  return { ok: true, applied, notes, restarted };
}

export const terrariaApplier: GameConfigApplier = { spec: TERRARIA_SPEC, apply };
import type { GameConfigApplierSpec } from "../../lib/game-config-appliers";

/**
 * The applier contract. Read docs/DOCUMENTATION.md "Game config appliers" first.
 *
 * An applier is `{ spec, apply }`. `spec` (lib/game-config-appliers.ts) declares
 * which schema fields it handles and how each takes effect; `apply` does the work
 * through `ctx.guest` (never ssh2 directly), so every applier is unit-testable
 * with an in-memory fake guest.
 */

export type Values = Record<string, string | number | boolean>;

export type ExecResult = { code: number; stdout: string; stderr: string };

/** The game server VM as an applier sees it. The framework builds this over SSH/SFTP. */
export interface Guest {
  exec(cmd: string, timeoutMs?: number): Promise<ExecResult>;
  /** null = the file does not exist. */
  readFile(path: string): Promise<string | null>;
  writeFile(path: string, content: string): Promise<void>;
}

/** What an applier returns. `notes`/`applied` are customer-facing and already redacted by the runner. */
export type ApplyOutcome = {
  ok: boolean;
  /** Sentences saying what really changed on the running server. */
  applied: string[];
  /** Everything else the customer should know (not applied, needs restart, kept old world, ...). */
  notes: string[];
  /** True when the apply itself restarted the game (lets the job layer skip a second restart). */
  restarted?: boolean;
  /**
   * True when EVERYTHING applied took effect in the running game with no restart
   * (rcon / live command). The job layer then never tells the customer "restart to apply".
   */
  live?: boolean;
};

export interface ApplierContext {
  family: string;
  server: { id: string; hostname?: string };
  /** Validated, fully populated settings for the family. */
  values: Values;
  /**
   * Schema keys the customer changed in THIS save (+ "variant"). undefined = unknown
   * (auto-queued at provision): treat every handled field as possibly changed, and
   * never do anything destructive-looking (e.g. switching worlds) on that basis.
   */
  changed: string[] | undefined;
  /** The handled fields this run should consider (handled ∩ changed, or all handled when `changed` is unknown). */
  touched: string[];
  guest: Guest;
  /** systemd unit supervising the game container (resolveGameUnit), or null on an older guest. */
  unit: string | null;
  /** Waits for the game port, using the family's window from lib/game-power-start.ts. null = no port known. */
  waitPort(): Promise<{ ok: boolean } | null>;
  /** True when the customer chose "Apply & restart". */
  restartRequested: boolean;
}

export interface GameConfigApplier {
  spec: GameConfigApplierSpec;
  apply(ctx: ApplierContext): Promise<ApplyOutcome>;
}

/** Single-quote a string for a POSIX shell. */
export const shq = (s: string) => `'${s.replace(/'/g, `'\\''`)}'`;
import type { GameConfigApplierSpec } from "../game-config-appliers";

/**
 * Terraria (ryshe/terraria = vanilla Terraria 1.4.5.6 + TShock 6.1) — PURE half:
 * the field spec plus every mapping the worker applier and the provisioning
 * script share, so a fresh install, a reinstall and a Settings save all produce
 * the same server. No I/O here.
 *
 * Where each schema field really lives (read off the image's bootstrap.sh, the
 * provisioning script in lib/terraria-plugins.ts, and TShock's own source):
 *
 *  - world-size / world-name / world-seed / difficulty: Terraria launch args
 *    `-autocreate N -worldname X -seed S -difficulty D`. They are read ONLY when
 *    the world file named by env WORLD_FILENAME does not exist yet. They never
 *    change an existing world. So the applier does what Valheim does: a new
 *    combination gets its OWN world file (name derived from the combination),
 *    the container is recreated pointing at it, and the previous world file is
 *    left on disk untouched. Choosing the old combination again switches back.
 *  - server-password, max-players, server-name, pvp-mode, spawn-protection,
 *    auto-save, kick-mediumcore-on-death: TShock keys in /opt/terraria/config.json
 *    (the host folder mounted at /tshock/tshock, TShock's -configpath). TShock
 *    reads them at startup, so they need a restart. There is NO -password launch
 *    arg in play on purpose: a CLI password would override config.json forever
 *    (TShock.OnPostInit/OnConfigRead), so config.json is the single place.
 */

export const TERRARIA_SPEC: GameConfigApplierSpec = {
  family: "terraria",
  fields: {
    "world-size": { when: "recreate", note: "Creates a NEW world with these settings and switches to it. Your current world is kept on the server and is not deleted." },
    "world-name": { when: "recreate", note: "Creates a NEW world with this name and switches to it. Your current world is kept. Change it back to return to that world." },
    "world-seed": { when: "recreate", note: "Only used when a new world is created. Your current world is kept." },
    difficulty: { when: "recreate", note: "Only used when a new world is created; it cannot change an existing world. Your current world is kept." },
    "server-name": { when: "restart" },
    "server-password": { when: "restart", secret: true },
    "max-players": { when: "restart", note: "TShock allows at most 235 players (255 minus its 20 reserved slots)." },
    "pvp-mode": { when: "restart" },
    "spawn-protection": { when: "restart" },
    "auto-save": { when: "restart" },
    "kick-mediumcore-on-death": { when: "restart" },
  },
};

export const TERRARIA_CONTAINER = "terraria";
export const TERRARIA_CONFIG_JSON = "/opt/terraria/config.json";
export const TERRARIA_WORLD_DIR = "/opt/terraria";
export const TERRARIA_MAX_SLOTS = 235;

/** The fields that define a world (only meaningful when a world is created). */
export const TERRARIA_WORLD_FIELDS = ["world-size", "world-name", "world-seed", "difficulty"] as const;
/** The fields that are TShock config.json keys. */
export const TERRARIA_CONFIG_FIELDS = [
  "server-name", "server-password", "max-players", "pvp-mode", "spawn-protection", "auto-save", "kick-mediumcore-on-death",
] as const;

export type TerrariaWorldSpec = { size: string; name: string; seed: string; difficulty: string };
type V = Record<string, string | number | boolean | undefined>;

export function terrariaWorldSpec(values: V): TerrariaWorldSpec {
  return {
    size: String(values["world-size"] ?? "2"),
    name: String(values["world-name"] ?? "Nxeon").trim() || "Nxeon",
    seed: String(values["world-seed"] ?? "").trim(),
    difficulty: String(values.difficulty ?? "0"),
  };
}

/** What the provisioning script creates today: `-autocreate 2 -worldname Nxeon`, file nxeon.wld. */
export const TERRARIA_DEFAULT_WORLD: TerrariaWorldSpec = { size: "2", name: "Nxeon", seed: "", difficulty: "0" };
export const TERRARIA_DEFAULT_WORLD_FILE = "nxeon.wld";

/** Small stable hash (FNV-1a) — file naming only, not security. */
function fnv(s: string): string {
  let h = 0x811c9dc5;
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    h = Math.imul(h, 0x01000193) >>> 0;
  }
  return h.toString(16).padStart(8, "0");
}

/**
 * The world file for a combination. The default combination keeps the legacy
 * `nxeon.wld` (so every existing server already "is" the default world); any
 * other combination gets `<name>-<hash>.wld`, unique per size/name/seed/difficulty.
 */
export function terrariaWorldFile(spec: TerrariaWorldSpec): string {
  if (JSON.stringify(spec) === JSON.stringify(TERRARIA_DEFAULT_WORLD)) return TERRARIA_DEFAULT_WORLD_FILE;
  const slug = spec.name.toLowerCase().replace(/[^a-z0-9]+/g, "").slice(0, 24) || "world";
  return `${slug}-${fnv(`${spec.size}|${spec.name}|${spec.seed}|${spec.difficulty}`)}.wld`;
}

/**
 * Rewrite a terraria container Cmd (array) for a world spec: replaces the value
 * of -autocreate/-worldname/-seed/-difficulty, adds the ones that are missing
 * (-seed only when non-blank, -difficulty only when not the default 0), drops a stale -seed/-difficulty, and keeps every other arg
 * (e.g. `-additionalplugins /tshock/CustomPlugins`) in order.
 */
export function terrariaCmdForWorld(cmd: string[], spec: TerrariaWorldSpec): string[] {
  const want: Record<string, string | null> = {
    "-autocreate": spec.size,
    "-worldname": spec.name,
    "-seed": spec.seed === "" ? null : spec.seed,
    "-difficulty": spec.difficulty === "0" ? null : spec.difficulty, // 0 (classic) is Terraria's own default
  };
  const out: string[] = [];
  const seen = new Set<string>();
  for (let i = 0; i < cmd.length; i++) {
    const a = cmd[i];
    if (a in want) {
      seen.add(a);
      i++; // skip its old value
      if (want[a] !== null) out.push(a, want[a] as string);
      continue;
    }
    out.push(a);
  }
  for (const k of Object.keys(want)) if (!seen.has(k) && want[k] !== null) out.push(k, want[k] as string);
  return out;
}

/** Cmd value of a flag, or null. */
export function cmdArg(cmd: string[], flag: string): string | null {
  const i = cmd.indexOf(flag);
  return i >= 0 && i + 1 < cmd.length ? cmd[i + 1] : null;
}

/** The TShock Settings keys for the config-json schema fields (only the keys asked for). */
export function terrariaTshockSettings(values: V, only?: readonly string[]): Record<string, string | number | boolean> {
  const want = (k: string) => !only || only.includes(k);
  const out: Record<string, string | number | boolean> = {};
  if (want("server-password")) out.ServerPassword = String(values["server-password"] ?? "");
  if (want("max-players")) out.MaxSlots = Math.min(Math.max(1, Math.trunc(Number(values["max-players"] ?? 8))), TERRARIA_MAX_SLOTS);
  if (want("server-name")) {
    const n = String(values["server-name"] ?? "").trim();
    out.ServerName = n;
    out.UseServerName = n.length > 0; // TShock only shows ServerName when UseServerName is true
  }
  if (want("pvp-mode")) out.PvPMode = String(values["pvp-mode"] ?? "Normal").toLowerCase(); // normal|always|pvpwithnoteam|disabled
  if (want("spawn-protection")) out.SpawnProtection = values["spawn-protection"] === true;
  if (want("auto-save")) out.AutoSave = values["auto-save"] === true;
  if (want("kick-mediumcore-on-death")) out.KickOnMediumcoreDeath = values["kick-mediumcore-on-death"] === true;
  return out;
}

/**
 * Bake a customer's settings into the provisioning script so a fresh install
 * and a "Wipe & reinstall" come up already configured (the worker applier only
 * runs on Settings saves). Pure string rewrite of lib/terraria-plugins.ts's
 * TERRARIA_SETUP_SCRIPT; returns the script unchanged if it is not that shape.
 */
export function applyTerrariaSetup(setupScript: string, values: V | null | undefined): string {
  if (!values) return setupScript;
  const re = /-e WORLD_FILENAME=\S+ (.*?)ryshe\/terraria:latest (.*)$/s;
  const m = re.exec(setupScript);
  if (!m) return setupScript;
  const spec = terrariaWorldSpec(values);
  const q = (s: string) => `'${s.replace(/'/g, `'\\''`)}'`;
  const args = terrariaCmdForWorld(m[2].trim().split(/\s+/), spec);
  const quoted = args.map((a, i) => (/^-(worldname|seed)$/.test(args[i - 1] ?? "") ? q(a) : a)).join(" ");
  let out = setupScript.replace(re, () => `-e WORLD_FILENAME=${terrariaWorldFile(spec)} ${m[1]}ryshe/terraria:latest ${quoted}`);
  // Seed TShock's config.json BEFORE first boot. TShock fills every key we leave out with its
  // default and rewrites the file (FileTools.LoadConfigAndCheckForChanges), so a partial file is safe.
  const json = JSON.stringify({ Settings: terrariaTshockSettings(values) });
  const seed = `mkdir -p ${TERRARIA_WORLD_DIR} && { [ -f ${TERRARIA_CONFIG_JSON} ] || printf '%s' ${q(json)} > ${TERRARIA_CONFIG_JSON}; } && `;
  out = out.replace("docker run -d --name terraria", () => `${seed}docker run -d --name terraria`);
  return out;
}

import type { Guest } from "../types";
import { shq } from "../types";

/**
 * Config-file strategy: read-modify-write ONE file on the guest with a backup,
 * verification and rollback.
 *
 *   read -> patch(old) -> validate(new) -> (identical? stop: idempotent no-op)
 *   -> backup (path.nxbak) -> write -> read back + validate -> done
 *
 * The patch function is one of kit/json-patch, ini-patch, kv-patch (or your own);
 * it must preserve keys it was not asked to change. Nothing is written when the
 * file is missing or does not parse. The caller decides what happens after
 * (restart etc.) and can still call `restore()` if a LATER step fails.
 */
export type FilePatchResult =
  | { status: "missing" }
  | { status: "invalid"; reason: string }
  | { status: "unchanged" }
  /** Written and verified. `restore` puts the previous content back; `commit` drops the backup. */
  | { status: "changed"; restore(): Promise<void>; commit(): Promise<void> }
  /** The write did not verify; the previous content was restored. */
  | { status: "failed"; reason: string };

export async function patchRemoteFile(
  guest: Guest,
  opts: {
    path: string;
    patch(old: string): string;
    /** Returns an error string if the content is not acceptable (checked before AND after writing). */
    validate?(content: string): string | null;
  },
): Promise<FilePatchResult> {
  const { path } = opts;
  const old = await guest.readFile(path);
  if (old === null) return { status: "missing" };

  let next: string;
  try {
    next = opts.patch(old);
  } catch {
    // Deliberately not echoing the parser's message: it can quote file content.
    return { status: "invalid", reason: `${path} could not be parsed, so it was left untouched.` };
  }
  const bad = opts.validate?.(next);
  if (bad) return { status: "invalid", reason: `${bad} ${path} was left untouched.` };
  if (next === old) return { status: "unchanged" };

  const backup = await guest.exec(`cp -p ${shq(path)} ${shq(path + ".nxbak")}`);
  if (backup.code !== 0) return { status: "failed", reason: `Could not back up ${path} first, so nothing was changed.` };

  const restore = async () => {
    await guest.writeFile(path, old);
    await guest.exec(`rm -f ${shq(path + ".nxbak")}`);
  };

  try {
    await guest.writeFile(path, next);
    const back = await guest.readFile(path);
    const backBad = back === null ? "missing after write" : back !== next ? "differs from what was written" : opts.validate?.(back);
    if (backBad) {
      await restore();
      return { status: "failed", reason: `${path} did not verify after writing (${backBad}); the previous version was restored.` };
    }
  } catch (e) {
    await restore().catch(() => undefined);
    return { status: "failed", reason: `Writing ${path} failed (${(e as Error).message.slice(0, 120)}); the previous version was restored.` };
  }
  return {
    status: "changed",
    restore,
    commit: async () => void (await guest.exec(`rm -f ${shq(path + ".nxbak")}`)),
  };
}
import type { Guest } from "../types";
import { shq } from "../types";

/**
 * Env-recreate strategy: rebuild a game container with changed environment
 * (and/or launch args) while keeping every volume. Generalises
 * worker/zomboid-admin.ts (same safety shape): the OLD container is kept,
 * renamed `<name>-old`, until the new one is verified; any failure puts it back
 * and restarts it if the game was running. A server the customer had stopped is
 * rebuilt but NOT started.
 *
 *   inspect old -> compute new env/cmd -> (equal? idempotent no-op)
 *   -> write 0600 env-file -> stop unit -> rename old -> docker create new
 *   (same ports, binds, log opts, user as the old one) -> start (if it was running)
 *   -> wait for the port -> VERIFY (env, cmd, binds and ports read back) -> remove old
 *
 * Supervisor: under systemd (`unit` set) it stops/starts the UNIT (never docker
 * directly — see resolveGameUnit in worker/game-config.ts); with no unit it falls
 * back to docker's own restart policy exactly like recreateGameContainer.
 *
 * Secrets: values travel in the 0600 env-file and are never put in a command
 * line; every failure note is built from fixed strings.
 */

export type RecreateOpts = {
  container: string;
  unit: string | null;
  /** Env changes: a string sets the variable, null removes it. */
  env?: Record<string, string | null>;
  /** Transform the container's launch args (Cmd). */
  cmd?: (old: string[]) => string[];
  /** Guest path for the transient 0600 env-file (removed after create). */
  envFile: string;
  /** Wait for the game port after start. Not fatal while the container is still running. */
  waitPort(): Promise<{ ok: boolean } | null>;
};

export type RecreateResult =
  | { status: "noop" }
  | { status: "recreated"; wasActive: boolean; notes: string[] }
  | { status: "failed"; note: string; rolledBack: boolean };

type Inspected = {
  image: string;
  env: Map<string, string>;
  cmd: string[];
  entrypoint: string[] | null;
  user: string;
  binds: string[];
  ports: string[];
  logOpts: Record<string, string>;
};

function parseInspect(stdout: string): Inspected | null {
  try {
    const o = JSON.parse(stdout.trim());
    const env = new Map<string, string>();
    for (const e of (o.Config?.Env ?? []) as string[]) {
      const i = e.indexOf("=");
      if (i > 0) env.set(e.slice(0, i), e.slice(i + 1));
    }
    env.delete("PATH");
    const pb = (o.HostConfig?.PortBindings ?? {}) as Record<string, { HostIp?: string; HostPort?: string }[] | null>;
    const ports: string[] = [];
    for (const [cp, list] of Object.entries(pb)) {
      for (const b of list ?? []) {
        const [port, proto = "tcp"] = cp.split("/");
        ports.push(`${b.HostIp ? b.HostIp + ":" : ""}${b.HostPort ?? ""}:${port}/${proto}`);
      }
    }
    return {
      image: String(o.Config?.Image ?? ""),
      env,
      cmd: (o.Config?.Cmd ?? []) as string[],
      entrypoint: (o.Config?.Entrypoint ?? null) as string[] | null,
      user: String(o.Config?.User ?? ""),
      binds: ((o.HostConfig?.Binds ?? []) as string[]).slice().sort(),
      ports: ports.sort(),
      logOpts: (o.HostConfig?.LogConfig?.Config ?? {}) as Record<string, string>,
    };
  } catch {
    return null;
  }
}

const inspect = (g: Guest, name: string) => g.exec(`docker inspect ${shq(name)} --format '{{json .}}'`);

async function isRunning(g: Guest, name: string): Promise<boolean> {
  const r = await g.exec(`docker inspect -f '{{.State.Running}}' ${shq(name)} 2>/dev/null`);
  return r.stdout.trim() === "true";
}

export async function recreateWithEnv(guest: Guest, o: RecreateOpts): Promise<RecreateResult> {
  const { container: c, unit } = o;
  const old = `${c}-old`;
  const fail = (note: string, rolledBack = false): RecreateResult => ({ status: "failed", note, rolledBack });

  // 0. Self-heal a half-finished earlier run (container missing, `-old` present).
  let insp = await inspect(guest, c);
  if (insp.code !== 0) {
    const oldInsp = await inspect(guest, old);
    if (oldInsp.code !== 0) return fail(`Could not find the "${c}" game container, so nothing was changed.`);
    const r = await guest.exec(`docker rename ${shq(old)} ${shq(c)}`);
    if (r.code !== 0) return fail(`Could not find the "${c}" game container, so nothing was changed.`);
    insp = await inspect(guest, c);
  }
  const cur = parseInspect(insp.stdout);
  if (!cur || !cur.image) return fail("Could not read the game container's settings, so nothing was changed.");

  // 1. Image defaults, so only user-set env is carried (and Entrypoint is only passed if overridden).
  let imgEnv = new Map<string, string>();
  let imgEntry: string[] | null | undefined;
  const ii = await guest.exec(`docker image inspect ${shq(cur.image)} --format '{{json .Config}}'`);
  if (ii.code === 0) {
    try {
      const cfg = JSON.parse(ii.stdout.trim());
      for (const e of (cfg.Env ?? []) as string[]) {
        const i = e.indexOf("=");
        if (i > 0) imgEnv.set(e.slice(0, i), e.slice(i + 1));
      }
      imgEntry = cfg.Entrypoint ?? null;
    } catch {
      imgEnv = new Map();
    }
  }

  // 2. Desired state + idempotent no-op.
  const wantEnv = new Map(cur.env);
  for (const [k, v] of Object.entries(o.env ?? {})) (v === null ? wantEnv.delete(k) : wantEnv.set(k, v));
  const wantCmd = o.cmd ? o.cmd(cur.cmd) : cur.cmd;
  const envSame = [...wantEnv].every(([k, v]) => cur.env.get(k) === v) && [...cur.env.keys()].every((k) => wantEnv.has(k));
  if (envSame && JSON.stringify(wantCmd) === JSON.stringify(cur.cmd)) return { status: "noop" };

  // 3. Build the create command from the OLD container's own config.
  const carried = [...wantEnv].filter(([k, v]) => imgEnv.get(k) !== v);
  const envText = carried.map(([k, v]) => `${k}=${v.replace(/\r?\n/g, " ")}`).join("\n") + (carried.length ? "\n" : "");
  const entryOverridden = !!cur.entrypoint && imgEntry !== undefined && JSON.stringify(cur.entrypoint) !== JSON.stringify(imgEntry);
  const cmdArgs = [...(entryOverridden ? cur.entrypoint!.slice(1) : []), ...wantCmd];
  const create = [
    `docker create --name ${shq(c)}`,
    ...Object.entries(cur.logOpts).map(([k, v]) => `--log-opt ${shq(`${k}=${v}`)}`),
    cur.user ? `--user ${shq(cur.user)}` : "",
    ...cur.ports.map((p) => `-p ${shq(p)}`),
    ...cur.binds.map((b) => `-v ${shq(b)}`),
    `--env-file ${shq(o.envFile)}`,
    entryOverridden ? `--entrypoint ${shq(cur.entrypoint![0])}` : "",
    shq(cur.image),
    ...cmdArgs.map(shq),
  ].filter(Boolean).join(" ");

  // 4. Swap. Everything from here on rolls back on failure.
  const wasActive = unit
    ? (await guest.exec(`systemctl is-active ${shq(unit)}`)).stdout.trim() === "active"
    : await isRunning(guest, c);
  const start = unit ? `systemctl start ${shq(unit)}` : `docker start ${shq(c)}`;
  const stop = unit ? `systemctl stop ${shq(unit)}` : `docker update --restart=no ${shq(c)} 2>/dev/null; docker stop ${shq(c)}`;

  let swapped = false;
  const cleanup = () => guest.exec(`rm -f ${shq(o.envFile)}`).catch(() => undefined);
  const rollback = async (): Promise<boolean> => {
    let ok = true;
    try {
      if (unit) await guest.exec(`systemctl stop ${shq(unit)}`, 120_000);
      if (swapped) {
        const r = await guest.exec(`docker rm -f ${shq(c)} >/dev/null 2>&1; docker rename ${shq(old)} ${shq(c)}`);
        ok = r.code === 0;
      }
      if (wasActive) ok = (await guest.exec(start, 120_000)).code === 0 && ok;
    } catch {
      ok = false;
    }
    await cleanup();
    return ok;
  };
  const failBack = async (why: string): Promise<RecreateResult> => {
    const ok = await rollback();
    return fail(
      ok ? `${why} Your previous configuration was restored.` : `${why} Restoring the previous container also failed — support has been alerted.`,
      ok,
    );
  };

  await guest.exec(`install -m 600 /dev/null ${shq(o.envFile)}`);
  await guest.writeFile(o.envFile, envText);
  const st = await guest.exec(stop, 120_000);
  if (st.code !== 0 || (await isRunning(guest, c))) {
    await cleanup();
    if (wasActive) await guest.exec(start, 120_000).catch(() => undefined);
    return fail("Could not stop the game cleanly, so nothing was changed.");
  }
  const rn = await guest.exec(`docker rm -f ${shq(old)} >/dev/null 2>&1; docker rename ${shq(c)} ${shq(old)}`);
  if (rn.code !== 0) {
    await cleanup();
    if (wasActive) await guest.exec(start, 120_000).catch(() => undefined);
    return fail("Could not replace the game container, so nothing was changed.");
  }
  swapped = true;
  const cr = await guest.exec(create, 120_000);
  await cleanup();
  if (cr.code !== 0) return failBack("Could not create the updated game container.");

  // 5. Start + wait.
  const notes: string[] = [];
  if (wasActive) {
    if ((await guest.exec(start, 120_000)).code !== 0) return failBack("The game did not start with the new settings.");
    const port = await o.waitPort();
    if (!(await isRunning(guest, c))) return failBack("The game did not come back up with the new settings.");
    if (port && !port.ok) notes.push("The game is running but wasn't answering yet when we checked — it may still be loading.");
  }

  // 6. Verify by reading the new container back.
  const after = parseInspect((await inspect(guest, c)).stdout);
  const envBad = !after || [...Object.entries(o.env ?? {})].some(([k, v]) => (v === null ? after.env.has(k) : after.env.get(k) !== v));
  const cmdBad = !after || JSON.stringify(after.cmd) !== JSON.stringify(wantCmd);
  const shapeBad = !after || JSON.stringify(after.binds) !== JSON.stringify(cur.binds) || JSON.stringify(after.ports) !== JSON.stringify(cur.ports);
  if (envBad || cmdBad) return failBack("Verification failed: the new container does not carry the new settings.");
  if (shapeBad) return failBack("Verification failed: the new container's ports or volumes differ from the old one.");

  await guest.exec(`docker rm -f ${shq(old)} >/dev/null 2>&1`);
  return { status: "recreated", wasActive, notes };
}
/**
 * INI / CFG patcher. Preserves comments (`;` and `#`), blank lines, key order,
 * unknown keys/sections and the file's line endings; only the requested keys
 * change. A missing key is appended at the end of its section (a missing
 * section is appended at the end of the file). Keys with no section use `section: ""`.
 */

export type IniEdit = { section?: string; key: string; value: string };

const isComment = (l: string) => /^\s*[;#]/.test(l);
const sectionOf = (l: string) => /^\s*\[([^\]]*)\]\s*$/.exec(l)?.[1] ?? null;

export function patchIni(content: string, edits: IniEdit[], opts: { caseSensitive?: boolean } = {}): string {
  const eol = content.includes("\r\n") ? "\r\n" : "\n";
  const sep = "=";
  const norm = (s: string) => (opts.caseSensitive === false ? s.toLowerCase() : s);
  const lines = content.length ? content.split(/\r?\n/) : [];
  if (lines.length && lines[lines.length - 1] === "") lines.pop();
  const done = new Set<number>();

  edits.forEach((e, idx) => {
    const sec = e.section ?? "";
    let cur = "";
    let secStart = sec === "" ? 0 : -1;
    let lastInSec = -1;
    for (let i = 0; i < lines.length; i++) {
      const s = sectionOf(lines[i]);
      if (s !== null) {
        cur = s;
        if (norm(cur) === norm(sec) && secStart < 0) { secStart = i; lastInSec = i; }
        continue;
      }
      if (norm(cur) !== norm(sec)) continue;
      if (!isComment(lines[i]) && lines[i].trim() !== "") lastInSec = i;
      if (isComment(lines[i])) continue;
      const at = lines[i].indexOf("=");
      if (at < 0) continue;
      if (norm(lines[i].slice(0, at).trim()) === norm(e.key)) {
        lines[i] = `${lines[i].slice(0, at).replace(/\s+$/, "")}${sep}${e.value}`;
        done.add(idx);
        return;
      }
    }
    // not found: append
    if (sec === "") {
      // before the first section header, after the last top-level key
      let at = lines.findIndex((l) => sectionOf(l) !== null);
      if (at < 0) at = lines.length;
      lines.splice(at, 0, `${e.key}${sep}${e.value}`);
    } else if (secStart >= 0) {
      lines.splice((lastInSec < 0 ? secStart : lastInSec) + 1, 0, `${e.key}${sep}${e.value}`);
    } else {
      if (lines.length && lines[lines.length - 1].trim() !== "") lines.push("");
      lines.push(`[${sec}]`, `${e.key}${sep}${e.value}`);
    }
  });
  return lines.join(eol) + eol;
}

/** Read one value; undefined if absent. */
export function readIni(content: string, section: string, key: string, caseSensitive = true): string | undefined {
  const norm = (s: string) => (caseSensitive ? s : s.toLowerCase());
  let cur = "";
  for (const l of content.split(/\r?\n/)) {
    const s = sectionOf(l);
    if (s !== null) { cur = s; continue; }
    if (isComment(l) || norm(cur) !== norm(section)) continue;
    const eq = l.indexOf("=");
    if (eq >= 0 && norm(l.slice(0, eq).trim()) === norm(key)) return l.slice(eq + 1).trim();
  }
  return undefined;
}
/**
 * JSON config patcher (TShock config.json, Enshrouded/Core Keeper style files).
 * Parses, sets only the requested paths, serialises with the file's own indent;
 * every key it was not asked to touch (and the key order) is preserved.
 * JSON has no comments, so none are lost; a file that is not valid JSON throws
 * and the caller writes nothing.
 */

export type JsonEdit = { path: string[]; value: unknown };

function detectIndent(content: string): string | number {
  const m = /\n([ \t]+)"/.exec(content);
  if (!m) return 2;
  return m[1].startsWith("\t") ? "\t" : m[1].length;
}

/** Apply edits. `root` (optional) is a wrapper object key: used when the file has it as an object (TShock's "Settings"). */
export function patchJson(content: string, edits: JsonEdit[], opts: { wrapper?: string } = {}): string {
  const doc = JSON.parse(content) as unknown;
  if (doc === null || typeof doc !== "object" || Array.isArray(doc)) throw new Error("config root is not a JSON object");
  let root = doc as Record<string, unknown>;
  if (opts.wrapper) {
    const w = root[opts.wrapper];
    if (w && typeof w === "object" && !Array.isArray(w)) root = w as Record<string, unknown>;
    // else: a flat file (older layout) — patch the root; the game wraps it itself.
  }
  for (const e of edits) {
    let cur = root;
    for (let i = 0; i < e.path.length - 1; i++) {
      const k = e.path[i];
      const next = cur[k];
      if (next === undefined || next === null || typeof next !== "object" || Array.isArray(next)) cur[k] = {};
      cur = cur[k] as Record<string, unknown>;
    }
    cur[e.path[e.path.length - 1]] = e.value;
  }
  const trailingNewline = content.endsWith("\n");
  return JSON.stringify(doc, null, detectIndent(content)) + (trailingNewline ? "\n" : "");
}

/** Read the value at a path (same wrapper rule as patchJson); undefined if absent. */
export function readJson(content: string, path: string[], opts: { wrapper?: string } = {}): unknown {
  let cur: unknown = JSON.parse(content);
  if (opts.wrapper && cur && typeof cur === "object" && !Array.isArray(cur)) {
    const w = (cur as Record<string, unknown>)[opts.wrapper];
    if (w && typeof w === "object" && !Array.isArray(w)) cur = w;
  }
  for (const k of path) {
    if (cur === null || typeof cur !== "object") return undefined;
    cur = (cur as Record<string, unknown>)[k];
  }
  return cur;
}
/**
 * KEY=VALUE patcher (server.properties and friends). Moved verbatim from
 * worker/game-config.ts so appliers can use it without importing the SSH/DB layer.
 */

/** Update `key=value` lines in place, preserving comments/unknown lines; append missing keys. */
export function updateKeyValue(content: string, updates: Record<string, string>): string {
  const lines = content.split(/\r?\n/);
  const seen = new Set<string>();
  for (let i = 0; i < lines.length; i++) {
    const trimmed = lines[i].trim();
    if (!trimmed || trimmed.startsWith("#") || trimmed.startsWith("!")) continue;
    const eq = lines[i].indexOf("=");
    if (eq < 0) continue;
    const key = lines[i].slice(0, eq).trim();
    if (Object.prototype.hasOwnProperty.call(updates, key)) {
      lines[i] = `${key}=${updates[key]}`;
      seen.add(key);
    }
  }
  for (const k of Object.keys(updates)) {
    if (!seen.has(k)) lines.push(`${k}=${updates[k]}`);
  }
  return lines.join("\n");
}

/** Read a `key=value` file into a map (comments/blank lines ignored). */
export function parseKeyValue(content: string): Record<string, string> {
  const out: Record<string, string> = {};
  for (const line of content.split(/\r?\n/)) {
    const t = line.trim();
    if (!t || t.startsWith("#") || t.startsWith("!")) continue;
    const eq = line.indexOf("=");
    if (eq < 0) continue;
    out[line.slice(0, eq).trim()] = line.slice(eq + 1).trim();
  }
  return out;
}
/**
 * Compare what we meant to write with what we read back from the guest.
 * Returns KEY NAMES only — never values — so a mismatch report can never leak
 * a password into a note, log or job result.
 */
export function verifyReadback(
  expected: Record<string, unknown>,
  actual: Record<string, unknown>,
): { ok: boolean; mismatched: string[] } {
  const mismatched = Object.keys(expected).filter((k) => String(actual[k] ?? "") !== String(expected[k] ?? ""));
  return { ok: mismatched.length === 0, mismatched };
}

/**
 * Per-game customization schema (MVP).
 *
 * A plain module (NO "use server") so it can be imported from server components,
 * "use server" action files AND the worker daemon alike — it holds no secrets and
 * performs no I/O.
 *
 * It declares, per game family, the available server *variants* (the loader/flavour
 * a player runs — Paper vs Vanilla, Carbon vs Oxide, …) and a versioned list of
 * *settings fields* that drive a dynamic UI. Fields are intentionally limited to
 * the handful of options players actually change, keyed on the game's own real
 * config keys (server.properties, PalWorldSettings.ini, cvars, …) — no invented
 * cvars — so a future real "apply" step can render them 1:1.
 *
 * Exports: `familyFor`, `schemaFor`, `validateConfig` plus the `GAME_CONFIG_SCHEMAS`
 * table and its types.
 */

/** Bump when the field set changes in a way the worker/apply step must notice. */
import { fieldRuleError } from "./game-field-rules";
import { APPLIER_SPECS, applierFieldApply, appliersEnabled, type FieldApply } from "./game-config-appliers";
import { FIVEM_LICENSE_KEY_PATTERN, FIVEM_GAME_BUILDS, FIVEM_LOCALES, FIVEM_KNOWN_ARTIFACTS } from "./fivem";

export const GAME_CONFIG_VERSION = 1;

export type FieldType = "enum" | "bool" | "int" | "string";

/**
 * When a setting takes effect:
 *  - "deploy": needs a server restart / redeploy (world seed, tickrate, …)
 *  - "live":   can be pushed to a running server (motd, pvp, max players, …)
 * MVP treats both the same (simulated apply) but the UI surfaces the distinction.
 */
export type FieldPhase = "deploy" | "live";

export type ConfigField = {
  /** The game's own config key (e.g. "max-players", "ServerPlayerMaxNum"). */
  key: string;
  label: string;
  /** UI grouping heading. */
  group: string;
  type: FieldType;
  default: string | number | boolean;
  /** enum only — {value,label} choices. */
  options?: { value: string; label: string }[];
  /**
   * enum only. When true and `options` is long, the settings UI renders a
   * type-to-filter combobox (components/customer/SearchableSelect.tsx)
   * instead of a plain native `<select>` — a flat dropdown of 100+ entries
   * has no usable way to find one. Leave unset for short option lists
   * (gamemode, difficulty, …), where a native select is simpler and fine.
   */
  searchable?: boolean;
  /** int only — inclusive bounds. */
  min?: number;
  max?: number;
  phase: FieldPhase;
  /** optional one-line helper shown under the field. */
  help?: string;
  /**
   * string fields only. When true, `validateConfig` rejects a blank value —
   * used for values with no sane platform default where the server is
   * genuinely non-functional / unjoinable without a customer-supplied
   * credential (e.g. DST's Klei cluster TOKEN — an online DST cluster
   * refuses to start at all without one). Enforced both at order-creation
   * time (lib/game-order.ts, BEFORE payment) and at settings-save time
   * (lib/actions-game-config.ts), so it gates checkout AND blocks a customer
   * from blanking it back out later. See DST.TOKEN below for the motivating
   * incident (added same-day as the family, 2026-08-31 audit).
   */
  required?: boolean;
  /** string only: minimum length of a non-blank value (enforced by validateConfig + shown inline in the wizard). */
  minLength?: number;
  /** string only: value may not appear inside the value of this other field key (Valheim: password vs world name). */
  notInsideField?: string;
  /** string only: the deploy wizard pre-fills a random value the customer can change. */
  suggest?: "password";
  /**
   * Override the docker `-e KEY=` name that `applyGameConfigEnv`
   * (worker/game-variant.ts) substitutes into, when it differs from `key`.
   *
   * Found live 2026-09-11: Valheim's World Name field is keyed `"world"` (a
   * readable schema key, matches the game's own `-world` flag name) but the
   * lloesche/valheim-server image's actual env var is `WORLD_NAME`.
   * `applyGameConfigEnv` matches literally on `field.key`, so `-e world=`
   * never appeared in the setup script and the customer's chosen world name
   * was silently dropped at provisioning — every Valheim server booted on
   * the catalog's hardcoded default world regardless of what was ordered.
   * Set this whenever a field's readable schema key isn't the literal env
   * var name the image expects.
   */
  envKey?: string;
  /**
   * string fields only. Inclusive length bounds checked in addition to the
   * global 256-char cap (UI uses `maxLength` for the input's own limit).
   */
  maxLength?: number;
  /**
   * string fields only. Regex SOURCE (compiled with the `u` flag, tested
   * against the whole value) the value must match — data, not a function, so
   * the schema stays serialisable into the client settings form.
   */
  pattern?: string;
  /** Shown when `pattern`/length rules reject a value. */
  patternError?: string;
};

/**
 * Per-field string rules (length + pattern), shared by `validateConfig`
 * (server) and the settings form (client) so both say the same thing.
 * Returns an error message or null. Blank values on a non-required field are
 * not rule-checked (blank means "unset").
 */
export function stringFieldError(field: ConfigField, v: string): string | null {
  if (field.type !== "string") return null;
  if (v.trim().length === 0) return null;
  if (field.minLength != null && v.length < field.minLength) {
    return `${field.label} must be at least ${field.minLength} characters.`;
  }
  if (field.maxLength != null && v.length > field.maxLength) {
    return `${field.label} is too long (max ${field.maxLength} characters).`;
  }
  if (field.pattern) {
    let re: RegExp | null = null;
    try {
      re = new RegExp(field.pattern, "u");
    } catch {
      re = null;
    }
    if (re && !re.test(v)) return field.patternError ?? `${field.label} contains characters that are not allowed.`;
  }
  return null;
}

export type GameVariant = {
  id: string;
  label: string;
  description?: string;
  /**
   * Plain-language reason this type can't be picked for a NEW order or switched
    // `admin` (worker/game-variant.ts applyGameConfigEnv), and provision()
    // persists "admin" for it (blankIdentityDefaults).
    { key: "ADMIN_USERNAME", label: "Admin Username", group: "Access", type: "string", default: "admin", phase: "deploy", help: "The in-game admin account's user name (leave blank for \"admin\"). Not applied to a running server — renaming an existing admin account isn't supported; this only takes effect on a fresh install." },
    { key: "ADMIN_PASSWORD", label: "Admin Password", group: "Access", type: "string", default: "", phase: "deploy", help: "Applies when you save: your server restarts for about a minute and the new password is checked before we say it worked. Used for the in-game admin login." },
    { key: "RCON_PASSWORD", label: "RCON Password", group: "Access", type: "string", default: "", phase: "deploy", help: "Prerequisite for any future console-command support." },
    { key: "MEMORY_XMX_GB", label: "Java Heap (GB)", group: "Performance", type: "int", default: 4, min: 2, max: 16, phase: "deploy", help: "JVM heap size — matters for stability vs. your plan's RAM." },
  ],
};

const SDTD: FamilySchema = {
  family: "sdtd",
  label: "7 Days to Die",
  defaultVariant: "vanilla",
