import { TERRARIA_SPEC } from "./game-applier-specs/terraria";

/** ONE line per family. The worker registry (worker/game-config-appliers/index.ts) must register the same spec. */
export const APPLIER_SPECS: Record<string, GameConfigApplierSpec> = {
  terraria: TERRARIA_SPEC,
};

/** Whether the applier framework is enabled (kill switch: NXEON_GAMECFG_APPLIERS=off). */
export function appliersEnabled(): boolean {
  return process.env.NXEON_GAMECFG_APPLIERS !== "off";
}

export function applierSpec(family: string | null | undefined): GameConfigApplierSpec | null {
  if (!family || !appliersEnabled()) return null;
  return APPLIER_SPECS[family] ?? null;
}

/** The mechanism for one field, or null when the field is saved only (or the family has no applier). */
export function applierFieldApply(family: string | null | undefined, key: string): FieldApply | null {
  return applierSpec(family)?.fields[key] ?? null;
}

