/**
 * Shared PURE helpers for the survival-game appliers (sdtd, vrising, enshrouded,
 * icarus, sunkenland, nightingale). No I/O, no node imports: the settings page,
 * the worker applier and the provisioning script all read the same tables.
 *
 * Five of the six families (all but sdtd) are driven by docker environment
 * variables that their image turns into the game's own config on EVERY start,
 * so the container's env is the source of truth: one `EnvField` table per
 * family says which schema field becomes which variable and how its value is
 * formatted. The worker applier rebuilds the container with that env, and the
 * provisioning script gets the very same variables baked in.
 */

export type Values = Record<string, string | number | boolean | undefined>;

/** Result of converting one schema value: the variable's value, null = leave/unset the variable, or an error to show the customer. */
export type EnvConv = string | null | { error: string };

export type EnvField = {
  /** Schema field key. */
  field: string;
  /** The real docker env variable the image reads. */
  env: string;
  conv(v: string | number | boolean | undefined, all: Values): EnvConv;
};

export type EnvPlan = {
  /** env var -> value (string) or null (remove it so the image default applies). */
  env: Record<string, string | null>;
  /** Customer-facing reasons a value cannot be applied (the whole apply is refused). */
  errors: string[];
};

export function buildEnv(table: readonly EnvField[], values: Values, only?: readonly string[]): EnvPlan {
  const env: Record<string, string | null> = {};
  const errors: string[] = [];
  for (const f of table) {
    if (only && !only.includes(f.field)) continue;
    const r = f.conv(values[f.field], values);
    if (r !== null && typeof r === "object") errors.push(r.error);
    else env[f.env] = r;
  }
  return { env, errors };
}

export const asBool = (v: unknown): boolean => v === true || v === "true";
export const boolStr = (v: unknown): string => (asBool(v) ? "true" : "false");
export const asStr = (v: unknown): string => (v === undefined || v === null ? "" : String(v));

export function clampInt(v: unknown, min: number, max: number, fallback: number): number {
  const n = Math.trunc(Number(v));
  if (!Number.isFinite(n)) return fallback;
  return Math.min(Math.max(n, min), max);
}

/** Reject values the images feed through sed / shell lines where a backslash or newline would corrupt the config. */
export function plainText(label: string, v: unknown, max = 128): string | { error: string } {
  const s = asStr(v);
  if (/[\\\r\n\0]/.test(s)) return { error: `${label} can't contain a backslash or a line break.` };
  if (s.length > max) return { error: `${label} is too long (max ${max} characters).` };
  return s;
}

/** A 5-field cron expression (the images pass it to crontab; a malformed one silently disables the job). */
export function cronError(label: string, v: unknown): string | null {
  const s = asStr(v).trim();
  if (s === "") return null;
  const parts = s.split(/\s+/);
  if (parts.length !== 5 || !parts.every((p) => /^[0-9*/,\-A-Za-z?]+$/.test(p))) {
    return `${label} must be a 5-field cron expression such as "0 */6 * * *", or blank to turn it off.`;
  }
  return null;
}

const shq = (s: string) => `'${s.replace(/'/g, `'\\''`)}'`;

/**
 * Bake env variables into a family's `docker run -d ...` setup script so a
 * fresh install and a "Wipe & reinstall" start configured:
 *  - a variable already present as `-e NAME=...` is REPLACED (any value, blanks included),
 *  - a missing one is INSERTED right after `docker run -d`, but only when it has a value
 *    (null/"" for a variable the script never set means "image default", i.e. nothing to add).
 * Returns the script unchanged when it is not a `docker run -d` script.
 */
export function bakeEnv(script: string, env: Record<string, string | null>): string {
  let out = script;
  const inserts: string[] = [];
  for (const [name, value] of Object.entries(env)) {
    if (value === null) continue;
    const re = new RegExp(`-e\\s+${name}=(?:'[^']*'|"[^"]*"|\\S*)`);
    if (re.test(out)) out = out.replace(re, () => `-e ${name}=${shq(value)}`);
    else if (value !== "") inserts.push(`-e ${name}=${shq(value)}`);
  }
  if (inserts.length) {
    const run = /(docker run\s+(?:-d|--detach)\b)/;
    if (!run.test(out)) return out;
    out = out.replace(run, (m) => `${m} ${inserts.join(" ")}`);
  }
  return out;
}

