import type { GameConfigApplierSpec } from "../game-config-appliers";
import { asStr, boolStr, buildEnv, clampInt, cronError, plainText, type EnvField, type Values } from "./survival-shared";

/**
 * Enshrouded (mornedhels/enshrouded-server) — PURE half.
 *
 * Truth, read off the image's own bootstrap script (scripts/default/enshrouded-bootstrap-shared)
