/**
 * Patcher for `<property name="X" value="Y"/>` style XML configs (7 Days to Die's serverconfig.xml
 * and friends). Text-level, so comments, ordering, indentation and unknown properties are all
 * preserved byte for byte; only the `value` of the requested properties changes. Matches inside
 * `<!-- ... -->` comments are ignored (the stock file documents properties in comments).
 * A missing property is appended just before the closing root tag.
 */

export type XmlPropEdit = { name: string; value: string; skipIfBlankAndMissing?: boolean };

const esc = (s: string) => s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
const unesc = (s: string) => s.replace(/&quot;/g, '"').replace(/&lt;/g, "<").replace(/&gt;/g, ">").replace(/&apos;/g, "'").replace(/&amp;/g, "&");

function commentRanges(content: string): [number, number][] {
  const out: [number, number][] = [];
  const re = /<!--[\s\S]*?-->/g;
  let m: RegExpExecArray | null;
  while ((m = re.exec(content))) out.push([m.index, m.index + m[0].length]);
  return out;
}
const inComment = (ranges: [number, number][], at: number) => ranges.some(([a, b]) => at >= a && at < b);

function findProp(content: string, name: string): { start: number; end: number; valueStart: number; valueEnd: number } | null {
  const ranges = commentRanges(content);
  const re = new RegExp(`<property\\s+name\\s*=\\s*"${name.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}"\\s+value\\s*=\\s*"([^"]*)"`, "g");
  let m: RegExpExecArray | null;
  while ((m = re.exec(content))) {
    if (inComment(ranges, m.index)) continue;
    const valueEnd = m.index + m[0].length - 1;
    return { start: m.index, end: m.index + m[0].length, valueStart: valueEnd - m[1].length, valueEnd };
  }
  return null;
}

export function readXmlProperty(content: string, name: string): string | undefined {
  const p = findProp(content, name);
  return p ? unesc(content.slice(p.valueStart, p.valueEnd)) : undefined;
}

export function patchXmlProperties(content: string, edits: XmlPropEdit[], opts: { root: string }): string {
  let out = content;
  const eol = out.includes("\r\n") ? "\r\n" : "\n";
  for (const e of edits) {
    const p = findProp(out, e.name);
    if (p) {
      out = out.slice(0, p.valueStart) + esc(e.value) + out.slice(p.valueEnd);
      continue;
    }
    if (e.skipIfBlankAndMissing && e.value === "") continue;
    const ranges = commentRanges(out);
    const closeRe = new RegExp(`</${opts.root}\\s*>`, "g");
    let close = -1;
    let m: RegExpExecArray | null;
    while ((m = closeRe.exec(out))) if (!inComment(ranges, m.index)) close = m.index;
    if (close < 0) throw new Error("closing root tag not found");
    const lineStart = out.lastIndexOf("\n", close - 1) + 1;
    const before = out.slice(lineStart, close);
    const at = before.trim() === "" ? lineStart : close;
    out = out.slice(0, at) + `  <property name="${e.name}" value="${esc(e.value)}"/>${eol}` + out.slice(at);
  }
  return out;
}
EOF

