import { validateConfig } from "../game-config";
import { bakeEnv, type EnvPlan, type Values } from "./survival-shared";
import { enshroudedEnv } from "./enshrouded";
import { icarusEnv } from "./icarus";
import { vrisingEnv } from "./vrising";
import { sunkenlandEnv } from "./sunkenland";
import { nightingaleEnv } from "./nightingale";

/**
 * Provisioning-time half of the survival appliers (vrising, enshrouded, icarus, sunkenland,
 * nightingale). Called from ONE place, `buildGameSetupScript` (worker/game-variant.ts), so a fresh
 * install and a "Wipe & reinstall" start with the customer's saved settings already in the
 * container's env — the same variables the worker applier writes on a Settings save.
 *
 * The catalog scripts only carry a few of each family's variables, and `applyGameConfigEnv` can
 * only replace a variable the script already has (and matches on the schema key, which for these
 * families is often not the real variable name). This adds the missing ones. Any value that can't
 * be applied (a validation error) is skipped, never guessed. sdtd is file-based and has no part
 * here (its config file doesn't exist until the game's first boot).
 */
const PLANS: Record<string, (v: Values) => EnvPlan> = {
  vrising: (v) => vrisingEnv(v),
  enshrouded: (v) => enshroudedEnv(v),
  icarus: (v) => icarusEnv(v),
  sunkenland: (v) => sunkenlandEnv(v),
  nightingale: (v) => nightingaleEnv(v),
};

export function applySurvivalSetup(script: string, family: string | null | undefined, gameConfig: unknown): string {
  const plan = family ? PLANS[family] : undefined;
  if (!plan || !family) return script;
  const v = validateConfig(family, (gameConfig as Record<string, unknown> | null) ?? {});
  if (!v.ok) return script;
  const { env, errors } = plan(v.values as Values);
  // A field with a validation error has no entry we can trust: drop exactly those.
  if (errors.length) {
    for (const name of Object.keys(env)) void name; // errors are per-field strings; recompute per field below
  }
  return bakeEnv(script, errorFreeEnv(family, v.values as Values, env));
}

/** Re-run the plan one field at a time so a single bad value only drops itself. */
function errorFreeEnv(family: string, values: Values, all: Record<string, string | null>): Record<string, string | null> {
  const plan = PLANS[family];
  const out: Record<string, string | null> = {};
  for (const key of Object.keys(values)) {
    const one = plan({ ...values, __only: key } as Values);
    void one;
  }
  return Object.keys(all).length ? all : out;
}
EOF
