import type { ApplierContext, ApplyOutcome, GameConfigApplier } from "./types";
import { patchRemoteFile } from "./kit/config-file";
import { patchIni, readIni } from "./kit/ini-patch";
import { patchXmlProperties, readXmlProperty } from "./kit/xml-property";
import { recreateWithEnv } from "./kit/env-recreate";
import { verifyReadback } from "./kit/readback";
import type { EnvPlan, Values } from "../../lib/game-applier-specs/survival-shared";
import { SDTD_SPEC, SDTD_CONFIG_XML, sdtdProperties } from "../../lib/game-applier-specs/sdtd";
import { VRISING_SPEC, VRISING_CONTAINER, vrisingEnv } from "../../lib/game-applier-specs/vrising";
import { ENSHROUDED_SPEC, ENSHROUDED_CONTAINER, enshroudedEnv } from "../../lib/game-applier-specs/enshrouded";
import { ICARUS_SPEC, ICARUS_CONTAINER, ICARUS_INI, ICARUS_INI_SECTION, ICARUS_INI_PASSWORDS, icarusEnv } from "../../lib/game-applier-specs/icarus";
import { SUNKENLAND_SPEC, SUNKENLAND_CONTAINER, sunkenlandEnv } from "../../lib/game-applier-specs/sunkenland";
import { NIGHTINGALE_SPEC, NIGHTINGALE_CONTAINER, nightingaleEnv } from "../../lib/game-applier-specs/nightingale";

/**
 * Appliers for the survival families. Mechanisms and the reasons for them live in each
 * lib/game-applier-specs/<family>.ts; this file only runs them.
 *
 *  - vrising / enshrouded / icarus / sunkenland / nightingale: env-recreate (the image turns its env
 *    into the game's config on every start, so the env is the source of truth). Icarus also edits
 *    ServerSettings.ini to CLEAR a password (the image ignores empty env values).
 *  - sdtd: config-file strategy on serverconfig (sdtdserver.xml); takes effect on restart.
 *
 * With no `changed` list (the job auto-queued at provision) an env family does nothing: its
 * settings were baked into the install script (lib/game-applier-specs/survival-setup.ts) and
 * rebuilding a brand-new container again would only restart it.
 */

const ALREADY_BAKED = "These settings were applied when the server was installed, so nothing needed changing.";

async function applyEnv(ctx: ApplierContext, o: { container: string; plan: EnvPlan; label: string; extra?: (ctx: ApplierContext) => Promise<{ restore?: () => Promise<void>; notes?: string[]; ok?: false }> }): Promise<ApplyOutcome> {
  if (ctx.changed === undefined) return { ok: true, applied: [], notes: [ALREADY_BAKED] };
  if (o.plan.errors.length) return { ok: false, applied: [], notes: [...o.plan.errors, "Nothing was changed on your server."] };

  const pre = o.extra ? await o.extra(ctx) : {};
  if (pre.ok === false) return { ok: false, applied: [], notes: pre.notes ?? [] };

  const r = await recreateWithEnv(ctx.guest, {
    container: o.container,
    unit: ctx.unit,
    env: o.plan.env,
    envFile: `/root/${o.container}.env`,
    waitPort: ctx.waitPort,
  });
  if (r.status === "failed") {
    if (pre.restore) await pre.restore().catch(() => undefined);
    return { ok: false, applied: [], notes: [r.note] };
  }
  if (r.status === "noop") return { ok: true, applied: [], notes: [...(pre.notes ?? []), `${o.label} already had these settings, so nothing needed changing.`] };
  const fields = ctx.touched.join(", ");
  const notes = [...(pre.notes ?? []), ...r.notes];
  if (r.wasActive) notes.push("Your server restarted briefly to apply this. Connected players were disconnected and can rejoin once it has loaded.");
  else notes.push("The server is stopped, so the new settings will be used the next time it starts.");
  return { ok: true, applied: [`Rebuilt the ${o.label} server with your new settings (${fields}).`], notes, restarted: r.wasActive };
}

const touchedPlan = (ctx: ApplierContext, f: (v: Values, only: string[]) => EnvPlan) => f(ctx.values, ctx.touched);

export const vrisingApplier: GameConfigApplier = {
  spec: VRISING_SPEC,
  apply: (ctx) => applyEnv(ctx, { container: VRISING_CONTAINER, label: "V Rising", plan: touchedPlan(ctx, vrisingEnv) }),
};
export const enshroudedApplier: GameConfigApplier = {
  spec: ENSHROUDED_SPEC,
  apply: (ctx) => applyEnv(ctx, { container: ENSHROUDED_CONTAINER, label: "Enshrouded", plan: touchedPlan(ctx, enshroudedEnv) }),
};
export const sunkenlandApplier: GameConfigApplier = {
  spec: SUNKENLAND_SPEC,
  apply: (ctx) => applyEnv(ctx, { container: SUNKENLAND_CONTAINER, label: "Sunkenland", plan: touchedPlan(ctx, sunkenlandEnv) }),
};
export const nightingaleApplier: GameConfigApplier = {
  spec: NIGHTINGALE_SPEC,
  apply: (ctx) => applyEnv(ctx, { container: NIGHTINGALE_CONTAINER, label: "Nightingale", plan: touchedPlan(ctx, nightingaleEnv) }),
};

// ---- Icarus: env-recreate + ini edit to clear a password --------------------------------------
async function icarusClearPasswords(ctx: ApplierContext): Promise<{ restore?: () => Promise<void>; notes?: string[]; ok?: false }> {
  // The image only copies NON-EMPTY env values into ServerSettings.ini, so a password the customer
  // blanked would otherwise survive in the ini. Edit the ini first; the recreate below then
  // restarts the game, which reads it.
  const blanked = ctx.touched.filter((k) => k in ICARUS_INI_PASSWORDS && String(ctx.values[k] ?? "") === "");
  if (!blanked.length) return {};
  const res = await patchRemoteFile(ctx.guest, {
    path: ICARUS_INI,
    patch: (old) => patchIni(old, blanked.map((k) => ({ section: ICARUS_INI_SECTION, key: ICARUS_INI_PASSWORDS[k], value: "" }))),
  });
  if (res.status === "invalid" || res.status === "failed") return { ok: false, notes: [res.reason, "Nothing was changed on your server."] };
  if (res.status !== "changed") return {}; // missing (never booted) or already blank: nothing to clear
  const back = await ctx.guest.readFile(ICARUS_INI);
  const actual: Record<string, unknown> = {};
  for (const k of blanked) actual[ICARUS_INI_PASSWORDS[k]] = back === null ? undefined : readIni(back, ICARUS_INI_SECTION, ICARUS_INI_PASSWORDS[k]);
  const rb = verifyReadback(Object.fromEntries(blanked.map((k) => [ICARUS_INI_PASSWORDS[k], ""])), actual);
  if (!rb.ok) {
    await res.restore();
    return { ok: false, notes: [`Verification failed for ${rb.mismatched.join(", ")}; Icarus's previous settings file was restored. Nothing was changed on your server.`] };
  }
  return { restore: res.restore, notes: [] };
}

export const icarusApplier: GameConfigApplier = {
  spec: ICARUS_SPEC,
  apply: async (ctx) => {
    let pre: { restore?: () => Promise<void> } = {};
    const out = await applyEnv(ctx, {
      container: ICARUS_CONTAINER,
      label: "Icarus",
      plan: touchedPlan(ctx, icarusEnv),
      extra: async (c) => {
        const r = await icarusClearPasswords(c);
        pre = r;
        return r;
      },
    });
    if (out.ok && pre.restore) {
      // The game restarted with the cleared ini; confirm it is still clear (a stopping server may rewrite its own file).
      const back = await ctx.guest.readFile(ICARUS_INI);
      const stale = ctx.touched.filter((k) => k in ICARUS_INI_PASSWORDS && String(ctx.values[k] ?? "") === "" && back !== null && (readIni(back, ICARUS_INI_SECTION, ICARUS_INI_PASSWORDS[k]) ?? "") !== "");
      if (stale.length) out.notes.push(`Icarus's settings file still holds an old value for ${stale.join(", ")}. Save again to clear it, or contact support.`);
      await ctx.guest.exec(`rm -f '${ICARUS_INI}.nxbak'`).catch(() => undefined);
    }
    return out;
  },
};

// ---- 7 Days to Die: serverconfig XML ---------------------------------------------------------
function validateSdtdXml(content: string): string | null {
  return /<ServerSettings[\s>]/.test(content) && /<\/ServerSettings\s*>/.test(content) ? null : "The result doesn't look like a 7 Days to Die server config.";
}

export const sdtdApplier: GameConfigApplier = {
  spec: SDTD_SPEC,
  apply: async (ctx) => {
    const props = sdtdProperties(ctx.values, ctx.touched);
    const res = await patchRemoteFile(ctx.guest, {
      path: SDTD_CONFIG_XML,
      patch: (old) => patchXmlProperties(old, props, { root: "ServerSettings" }),
      validate: validateSdtdXml,
    });
    if (res.status === "invalid" || res.status === "failed") return { ok: false, applied: [], notes: [res.reason, "Nothing was changed on your server."] };
    if (res.status === "missing") {
      return {
        ok: true,
        applied: [],
        notes: ["7 Days to Die hasn't created its settings file yet (the game has not finished its first start), so these settings were saved but not applied: " + ctx.touched.join(", ") + ". Start the server once and let it finish loading, then save again."],
      };
    }
    if (res.status === "unchanged") return { ok: true, applied: [], notes: ["The server's settings file already matched, so nothing needed changing."] };
    const back = await ctx.guest.readFile(SDTD_CONFIG_XML);
    const want: Record<string, unknown> = {};
    const actual: Record<string, unknown> = {};
    for (const p of props) {
      const got = back === null ? undefined : readXmlProperty(back, p.name);
      if (p.skipIfBlankAndMissing && p.value === "" && got === undefined) continue;
      want[p.name] = p.value;
      actual[p.name] = got;
    }
    const rb = verifyReadback(want, actual);
    if (!rb.ok) {
      await res.restore();
      return { ok: false, applied: [], notes: [`Verification failed for ${rb.mismatched.join(", ")}; the previous settings file was restored. Nothing was changed on your server.`] };
    }
    await res.commit();
    return { ok: true, applied: [`Updated the server's settings file (${ctx.touched.join(", ")}). They take effect when the server restarts.`], notes: [] };
  },
};
EOF
