for (const [field, value, prop, expected] of [
  ["ServerName", "Nxeon & Co <Survival>", "ServerName", "Nxeon & Co <Survival>"],
  ["ServerMaxPlayerCount", 12, "ServerMaxPlayerCount", "12"],
  ["ServerPassword", 'p"ass&1', "ServerPassword", 'p"ass&1'],
  ["SandboxCode", "AbC123-xyz_==", "SandboxCode", "AbC123-xyz_=="],
] as [string, string | number, string, string][]) {
  test(`sdtd.${field} -> <property name="${prop}"> (escaped, comments + other properties untouched, no restart)`, async () => {
    const g = sdtdGuest();
    const out = await sdtdRun(g, { [field]: value });
    assert.equal(out.ok, true, out.notes.join(" "));
    assert.equal(readXmlProperty(xmlOf(g), prop), expected);
    assert.equal(readXmlProperty(xmlOf(g), "ServerPort"), "26900");
