  vrising: `curl -fsSL https://get.docker.com | sh && docker run -d --name vrising -p 9876:9876/udp -p 9877:9877/udp -v /opt/vrising/server:/mnt/vrising/server -v /opt/vrising/persistentdata:/mnt/vrising/persistentdata -e TZ='Etc/UTC' -e SERVERNAME='Nxeon' -e HOST_SETTINGS_Password='changeme12' -e HOST_SETTINGS_MaxConnectedUsers='40' -e GAME_SETTINGS_GameModeType='PvP' --restart unless-stopped trueosiris/vrising`,
  enshrouded: `curl -fsSL https://get.docker.com | sh && docker run -d --name enshrouded --stop-timeout 90 -p 15636:15636/udp -p 15637:15637/udp -v /opt/enshrouded:/opt/enshrouded -e SERVER_NAME='Nxeon' -e SERVER_PASSWORD='changeme12' -e SERVER_SLOT_COUNT='16' -e SERVER_QUERYPORT='15637' -e UPDATE_CRON='*/30 * * * *' -e PUID='4711' -e PGID='4711' --restart unless-stopped mornedhels/enshrouded-server:latest`,
  icarus: `curl -fsSL https://get.docker.com | sh && mkdir -p /opt/icarus/data /opt/icarus/game && docker run -d --name icarus --hostname icarus --restart unless-stopped --stop-timeout 90 -p 17777:17777/udp -p 27015:27015/udp -e SERVER_NAME='Nxeon' -e SERVER_PASSWORD='' -e SERVER_ADMIN_PASSWORD='changeme12' -e SERVER_PORT='17777' -e SERVER_QUERYPORT='27015' -e PUID='4711' -e PGID='4711' -v /opt/icarus/data:/home/icarus/drive_c/icarus -v /opt/icarus/game:/opt/icarus mornedhels/icarus-server:latest`,
  sunkenland: `curl -fsSL https://get.docker.com | sh && mkdir -p /opt/sunkenland/Worlds /opt/sunkenland/game /opt/sunkenland/Steam && docker run -d --name sunkenland --restart unless-stopped -p 27015:27015/udp -p 27016:27016/udp -e GAME_WORLD_GUID='nxeon-world' -v /opt/sunkenland/Worlds:/sunkenland/Worlds -v /opt/sunkenland/game:/sunkenland/game -v /opt/sunkenland/Steam:/sunkenland/Steam melle2/sunkenland-ds:latest`,
  nightingale: `curl -fsSL https://get.docker.com | sh && mkdir -p /opt/nightingale/config /opt/nightingale/savedata && docker run -d --name nightingale --hostname nightingale --restart unless-stopped -p 7777:7777/tcp -p 7777:7777/udp -e MAXPLAYERS='4' -e PUID='1000' -e PGID='1000' -e CONNECTIONPASSWORD='changeme12' -v /opt/nightingale/config:/config -v /opt/nightingale/savedata:/config/gamefiles/NWX/Saved fireblade004/nightingale-server:latest`,
};
const built = (family: string, gameConfig: V | null) => buildGameSetupScript({ osTemplate: { setupScript: SCRIPTS[family], family }, gameVariant: null, gameConfig }) as string;
const hasEnv = (s: string, k: string, v: string) => assert.ok(s.includes(`-e ${k}='${v}'`) || s.includes(`-e ${k}=${v} `), `${k}=${v} missing in:\n${s.slice(0, 900)}`);

test("setup script bakes every mapped field for a fresh install / reinstall (replacing placeholders, adding missing variables)", () => {
  let s = built("vrising", { ServerName: "Keep", MaxConnectedUsers: 30, GameModeType: "PvE", ClanSize: 3, Password: "pw-v", ListOnSteam: false });
  for (const [k, v] of [["SERVERNAME", "Keep"], ["HOST_SETTINGS_MaxConnectedUsers", "30"], ["GAME_SETTINGS_GameModeType", "PvE"], ["GAME_SETTINGS_ClanSize", "3"], ["HOST_SETTINGS_Password", "pw-v"], ["HOST_SETTINGS_ListOnSteam", "false"]]) hasEnv(s, k, v);
  assert.ok(!s.includes("changeme12"));
  s = built("enshrouded", { SERVER_NAME: "E", SERVER_SLOT_COUNT: 5, gameSettingsPreset: "Survival", SERVER_ENABLE_VOICE_CHAT: false, SERVER_VOICE_CHAT_MODE: "Global", SERVER_ENABLE_TEXT_CHAT: false, BACKUP_CRON: "0 */6 * * *" });
  for (const [k, v] of [["SERVER_NAME", "E"], ["SERVER_SLOT_COUNT", "5"], ["SERVER_GS_PRESET", "Survival"], ["SERVER_ENABLE_VOICE_CHAT", "false"], ["SERVER_VOICE_CHAT_MODE", "Global"], ["SERVER_ENABLE_TEXT_CHAT", "false"], ["BACKUP_CRON", "0 */6 * * *"]]) hasEnv(s, k, v);
  s = built("icarus", { SERVER_NAME: "I", SERVER_MAX_PLAYERS: 4, SERVER_PASSWORD: "jp", SERVER_ADMIN_PASSWORD: "ap-secret", SERVER_ALLOW_NON_ADMINS_LAUNCH: false, SERVER_SHUTDOWN_IF_EMPTY: -1 });
  for (const [k, v] of [["SERVER_NAME", "I"], ["SERVER_MAX_PLAYERS", "4"], ["SERVER_PASSWORD", "jp"], ["SERVER_ADMIN_PASSWORD", "ap-secret"], ["SERVER_ALLOW_NON_ADMINS_LAUNCH", "False"], ["SERVER_SHUTDOWN_IF_EMPTY", "-1.000000"]]) hasEnv(s, k, v);
  s = built("sunkenland", { worldGuid: "my-guid", maxPlayers: 9, password: "pw8", sessionInvisible: true });
  for (const [k, v] of [["GAME_WORLD_GUID", "my-guid"], ["GAME_MAX_PLAYER", "9"], ["GAME_PASSWORD", "pw8"], ["GAME_SESSION_INVISIBLE", "true"]]) hasEnv(s, k, v);
  s = built("nightingale", { CONNECTIONPASSWORD: "np", ADMINPASSWORD: "na-secret", MAXPLAYERS: 8, STARTINGDIFFICULTY: "extreme", ENABLECHEATS: true });
  for (const [k, v] of [["CONNECTIONPASSWORD", "np"], ["ADMINPASSWORD", "na-secret"], ["MAXPLAYERS", "8"], ["STARTINGDIFFICULTY", "extreme"], ["ENABLECHEATS", "true"]]) hasEnv(s, k, v);
});
test("setup script: an invalid value is skipped (never guessed); non-survival and null configs are untouched; the script still starts with docker run", () => {
  const raw = SCRIPTS.sunkenland;
  assert.equal(applySurvivalSetup(raw, "terraria", {}), raw);
  assert.equal(applySurvivalSetup(raw, "sunkenland", { worldGuid: "" }), raw, "required GUID missing -> validateConfig fails -> untouched");
  const s = applySurvivalSetup(raw, "sunkenland", { worldGuid: "g1", password: "waytoolongpw" });
  assert.ok(s.includes("GAME_WORLD_GUID='g1'"));
  assert.ok(!s.includes("GAME_PASSWORD"), "bad password dropped, not truncated");
  assert.match(bakeEnv("echo hi", { A: "1" }), /^echo hi$/);
});
test("baked setup script still wraps into the systemd game unit (create + unit) with the new env inside", () => {
  const s = built("enshrouded", { SERVER_SLOT_COUNT: 7 });
  assert.match(s, /docker create --name enshrouded/);
  assert.match(s, /-e SERVER_SLOT_COUNT='7'/);
});
EOF
